package com.bn.atmcontratos.config;
import com.bn.atmcontratos.model.entity.*; import com.bn.atmcontratos.model.enums.*; import com.bn.atmcontratos.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder; import java.math.*; import java.time.*;
@Configuration @RequiredArgsConstructor public class DataInitializer{
 private final UsuarioRepository users; private final ProveedorRepository proveedores; private final AtmRepository atms; private final ContratoRepository contratos; private final PasswordEncoder encoder;
 @Bean CommandLineRunner init(){return args->{ if(!users.existsByUsername("admin"))users.save(Usuario.builder().username("admin").password(encoder.encode("admin123")).nombreCompleto("Administrador").rol(RolNombre.ADMIN).build()); if(proveedores.count()==0){Proveedor p=proveedores.save(Proveedor.builder().ruc("20100000001").razonSocial("EXPOMALL S.A.C.").nombreContacto("Encargado de contratos").telefonoContacto("999999999").correoContacto("contacto@expomall.pe").build()); Atm a=atms.save(Atm.builder().codigoTerminal("S1AD1654").departamento("LA LIBERTAD").ciudad("TRUJILLO").distrito("TRUJILLO").direccion("Av. Mansiche N°1721").ubicacion("CC EXPOMALL MANSICHE").tipoAtmIsla("ISLA").coordenadaX(new BigDecimal("-8.1116")).coordenadaY(new BigDecimal("-79.0287")).proveedor(p).build()); Contrato c=Contrato.builder().numeroContrato("CO-029785-2024-BN").nombreContrato("Primera Adenda al Contrato N° CO-029785-2024-BN").tipoContrato("ARRENDAMIENTO").proveedor(p).responsableActas("Presenciales").meses("15").rentaMensual(new BigDecimal("700.00")).impuesto("sin incluir IGV").incluyeIgv(false).montoTotalMensual(new BigDecimal("700.00")).montoContrato(new BigDecimal("10500.00")).moneda("US$").fechaSuscripcion(LocalDate.of(2025,7,16)).fechaInicio(LocalDate.of(2025,9,1)).fechaFin(LocalDate.of(2026,11,30)).build(); c.getAtms().add(a); contratos.save(c); } }; }
}
